input.new_string:
.favicon {
  width: 34px; height: 34px; border-radius: 8px;
  background: var(--accent-soft);
  display: grid; place-items: center;
  font-weight: 700; color: var(--accent);
  flex: none; font-size: 15px; overflow: hidden;
}
.favicon img { width: 22px; height: 22px; display: block; }
.card .body { flex: 1; min-width: 0; }
.card .preview {
  width: 100%; height: 132px; object-fit: cover;
  border-radius: 8px; margin-bottom: 8px; display: block;
  border: 1px solid var(--line);
}
.card .title { font-weight: 600; font-size: 15px; margin: 0 0 3px; }
.card .desc { color: var(--muted); font-size: 13px; margin: 0 0 6px; line-height: 1.4; }
.card .site { color: var(--accent); font-size: 12px; word-break: break-all; }
.card.saving { opacity: .7; }
.card.flash { animation: flash 1.4s ease; }
@keyframes flash {
  0% { box-shadow: 0 0 0 0 rgba(37,99,235,.0); border-color: var(--accent); }
  25% { box-shadow: 0 0 0 4px rgba(37,99,235,.18); border-color: var(--accent); }
  100% { box-shadow: 0 0 0 0 rgba(37,99,235,0); border-color: var(--line); }
}
.toast {
  position: fixed; left: 50%; bottom: 24px; transform: translateX(-50%);
  background: var(--ink); color: #fff; padding: 12px 18px; border-radius: 10px;
  font-size: 14px; box-shadow: 0 8px 24px rgba(0,0,0,.2); opacity: 0;
  transition: opacity .25s, transform .25s; pointer-events: none; max-width: 90vw;
}
.toast.show { opacity: 1; transform: translateX(-50%) translateY(-4px); }

