.toast.show { opacity: 1; transform: translateX(-50%) translateY(-4px); }

.card.clickable { cursor: pointer; transition: box-shadow .15s; }
.card.clickable:hover { box-shadow: 0 3px 12px rgba(0,0,0,.07); }
.note {
  margin: 6px 0 0; font-size: 13px; color: var(--ink);
  background: #fffbea; border: 1px solid #f4e6a8; border-radius: 8px; padding: 8px 10px;
  white-space: pre-wrap;
}
.tags { margin-top: 8px; display: flex; flex-wrap: wrap; gap: 6px; }
.tag {
  font-size: 12px; background: var(--accent-soft); color: var(--accent);
  padding: 3px 9px; border-radius: 999px; font-weight: 600;
}
/* editor modal */
.backdrop {
  position: fixed; inset: 0; background: rgba(15,20,30,.45);
  display: none; align-items: flex-start; justify-content: center;
  padding: 40px 16px; overflow-y: auto; z-index: 50;
}
.backdrop.open { display: flex; }
.modal {
  background: var(--card); border-radius: 14px; width: 100%; max-width: 520px;
  padding: 22px; box-shadow: 0 20px 60px rgba(0,0,0,.25); animation: pop .2s ease;
}
.modal h2 { margin: 0 0 4px; font-size: 18px; }
.modal .sub { margin: 0 0 16px; color: var(--muted); font-size: 13px; word-break: break-all; }
.field { margin-bottom: 14px; }
.field label { display: block; font-size: 13px; font-weight: 600; margin-bottom: 5px; }
.field input[type=text], .field textarea {
  width: 100%; padding: 10px 12px; border: 1px solid var(--line);
  border-radius: 8px; font-size: 14px; font-family: inherit;
}
.field textarea { resize: vertical; min-height: 60px; }
.chipbox {
  display: flex; flex-wrap: wrap; gap: 6px; align-items: center;
  border: 1px solid var(--line); border-radius: 8px; padding: 7px 8px;
}
.chipbox .chip {
  display: inline-flex; align-items: center; gap: 6px;
  background: var(--accent-soft); color: var(--accent); font-weight: 600;
  font-size: 12px; padding: 3px 4px 3px 9px; border-radius: 999px;
}
.chipbox .chip button {
  border: none; background: transparent; color: var(--accent); cursor: pointer;
  font-size: 14px; line-height: 1; padding: 0 3px;
}
.chipbox input {
  border: none; outline: none; flex: 1; min-width: 120px; font-size: 14px; padding: 4px;
}
.modal .actions { display: flex; justify-content: flex-end; gap: 10px; margin-top: 18px; }
.btn {
  padding: 10px 18px; border-radius: 8px; font-size: 14px; font-weight: 600; cursor: pointer;
  border: 1px solid var(--line); background: #fff; color: var(--ink);
}
.btn.primary { background: var(--accent); color: #fff; border-color: var(--accent); }

