// --- Editor ---
const backdrop = document.getElementById("backdrop");
const editUrl = document.getElementById("editUrl");
const editTitle = document.getElementById("editTitle");
const editDesc = document.getElementById("editDesc");
const editNote = document.getElementById("editNote");
const chipbox = document.getElementById("chipbox");
const tagInput = document.getElementById("tagInput");
let editingKey = null;
let draftTags = [];

function renderChips() {
  chipbox.querySelectorAll(".chip").forEach(c => c.remove());
  draftTags.forEach((t, i) => {
    const chip = document.createElement("span");
    chip.className = "chip";
    chip.innerHTML = `${escapeHtml(t)} <button type="button" aria-label="Remove tag">×</button>`;
    chip.querySelector("button").addEventListener("click", () => {
      draftTags.splice(i, 1); renderChips();
    });
    chipbox.insertBefore(chip, tagInput);
  });
}
function addTagFromInput() {
  const raw = tagInput.value.trim().replace(/,$/, "").trim();
  if (!raw) return;
  if (!draftTags.some(t => t.toLowerCase() === raw.toLowerCase())) draftTags.push(raw);
  tagInput.value = "";
  renderChips();
}
tagInput.addEventListener("keydown", (e) => {
  if (e.key === "Enter" || e.key === ",") { e.preventDefault(); addTagFromInput(); }
  else if (e.key === "Backspace" && !tagInput.value && draftTags.length) {
    draftTags.pop(); renderChips();
  }
});
tagInput.addEventListener("blur", addTagFromInput);

function openEditor(key) {
  const b = bookmarks.find(x => x.key === key);
  if (!b) return;
  editingKey = key;
  editUrl.textContent = b.url;
  editTitle.value = b.title || "";
  editDesc.value = b.desc || "";
  editNote.value = b.note || "";
  draftTags = (b.tags || []).slice();
  tagInput.value = "";
  renderChips();
  backdrop.classList.add("open");
  editTitle.focus();
}
function closeEditor() {
  backdrop.classList.remove("open");
  editingKey = null;
}
document.getElementById("cancelEdit").addEventListener("click", closeEditor);
backdrop.addEventListener("click", (e) => { if (e.target === backdrop) closeEditor(); });
document.addEventListener("keydown", (e) => { if (e.key === "Escape" && backdrop.classList.contains("open")) closeEditor(); });
document.getElementById("saveEdit").addEventListener("click", () => {
  addTagFromInput();
  const b = bookmarks.find(x => x.key === editingKey);
  if (b) {
    b.title = editTitle.value.trim() || b.title;
    b.desc = editDesc.value.trim();
    b.note = editNote.value.trim();
    b.tags = draftTags.slice();
  }
  const key = editingKey;
  closeEditor();
  render();
  flashCard(key);
  showToast("Saved your changes.");
});

render();
document.body.setAttribute("data-harness-ready", "true");

