.tabs { display: flex; gap: 8px; margin-top: 22px; }
.tab {
  border: 1px solid var(--line); background: #fff; color: var(--muted);
  border-radius: 999px; padding: 8px 16px; font-size: 14px; font-weight: 600; cursor: pointer;
}
.tab.active { background: var(--ink); color: #fff; border-color: var(--ink); }
.tab .count {
  display: inline-block; min-width: 18px; text-align: center; font-size: 12px;
  background: var(--accent); color: #fff; border-radius: 999px; padding: 0 6px; margin-left: 4px;
}
.tab.active .count { background: rgba(255,255,255,.25); }
.col-actions { display: flex; flex-direction: column; gap: 6px; align-items: stretch; }
.readlater-btn {
  border: 1px solid var(--line); background: #fff; color: var(--muted);
  border-radius: 8px; padding: 6px 10px; font-size: 12px; font-weight: 600; cursor: pointer;
  white-space: nowrap;
}
.readlater-btn.on { background: #fff7e6; border-color: #f0c469; color: #b7791f; }
.toread-flag {
  display: inline-block; font-size: 11px; font-weight: 700; color: #b7791f;
  background: #fff7e6; border: 1px solid #f0c469; border-radius: 999px;
  padding: 1px 8px; margin-bottom: 4px;
}
.card.clickable { cursor: pointer; transition: box-shadow .15s; }

