let currentView = "all";
let searchQuery = "";
function matchesSearch(b, q) {
  if (!q) return true;
  const hay = [b.title, b.desc, b.note, b.url, ...(b.tags || [])].join(" ").toLowerCase();
  // every whitespace-separated term must be present
  return q.toLowerCase().split(/\s+/).filter(Boolean).every(term => hay.includes(term));
}
function visibleBookmarks() {
  return bookmarks.filter(b =>
    (currentView === "toread" ? b.readLater : true) && matchesSearch(b, searchQuery)
  );
}

