function mk(o){return Object.assign({title:'',desc:'',note:'',url:'',tags:[]},o);}
const items = {
  A: mk({title:'Rome travel guide', tags:['article','travel']}),
  B: mk({title:'History of Rome', tags:['book']}),
  C: mk({title:'Paris food', tags:['article']}),
  D: mk({note:'this or that', tags:['misc']}),
  E: mk({title:'quarterly report draft', tags:['work']}),
  F: mk({title:'reading list', tags:['reading']}),
  G: mk({title:'a great read', tags:['toread']}),
};
function run(q){
  const node = parseQuery(q);
  const hit = Object.entries(items).filter(([k,b])=>evalQuery(node,b)).map(([k])=>k);
  console.log(JSON.stringify(q), '->', hit.join(',')||'(none)');
}
