// --- Delete confirmation ---
const confirmBackdrop = document.getElementById("confirmBackdrop");
const confirmTarget = document.getElementById("confirmTarget");
let deleteKey = null;
function askDelete(key) {
  const b = bookmarks.find(x => x.key === key);
  if (!b) return;
  deleteKey = key;
  confirmTarget.textContent = b.title || b.url;
  confirmBackdrop.classList.add("open");
}
function closeConfirm() { confirmBackdrop.classList.remove("open"); deleteKey = null; }
document.getElementById("cancelDelete").addEventListener("click", closeConfirm);
confirmBackdrop.addEventListener("click", (e) => { if (e.target === confirmBackdrop) closeConfirm(); });
document.addEventListener("keydown", (e) => { if (e.key === "Escape" && confirmBackdrop.classList.contains("open")) closeConfirm(); });
document.getElementById("confirmDelete").addEventListener("click", () => {
  bookmarks = bookmarks.filter(x => x.key !== deleteKey);
  closeConfirm();
  render();
  showToast("Bookmark deleted permanently.");
});

