// --- Optional sample data for edge-case review (only with ?seed=1) ---
function seedSampleData() {
  const sites = [
    "github.com","en.wikipedia.org","nytimes.com","youtube.com","developer.mozilla.org",
    "medium.com","stackoverflow.com","arxiv.org","bbc.com","theguardian.com",
    "reddit.com","news.ycombinator.com","css-tricks.com","smashingmagazine.com","figma.com"
  ];
  const sampleTags = ["reading","article","book","work","recipe","travel","reference","video","tutorial"];
  const out = [];
  for (let i = 0; i < 42; i++) {
    const host = sites[i % sites.length];
    const url = "https://" + host + "/page-" + (i + 1);
    const meta = metadataFor(url);
    const tagCount = i % 5;
    const tags = sampleTags.slice(0, tagCount);
    out.push({
      url, key: normalizeUrl(url), loading: false,
      title: meta.title + " #" + (i + 1),
      desc: meta.desc, favicon: meta.favicon, preview: (i % 3 === 0) ? meta.preview : null,
      note: (i % 4 === 0) ? "Saved for later — check the **key section** and the [link](https://example.com)." : "",
      tags, readLater: (i % 6 === 0), archived: (i % 9 === 0),
    });
  }
  // One deliberately extreme item: very long title, description, url, note, many tags.
  const longUrl = "https://example.com/" + "very-long-path-segment/".repeat(8) + "end";
  out.unshift({
    url: longUrl, key: normalizeUrl(longUrl), loading: false,
    title: "An unusually long bookmark title that keeps going well beyond what would normally fit on a single line so we can see how the card handles wrapping without breaking the layout",
    desc: "This description is intentionally verbose. ".repeat(12),
    favicon: faviconUrl("example.com"), preview: null,
    note: "Long note with formatting:\n\n- first **important** point\n- second point with a [reference](https://example.com)\n- third point mentioning `some code`\n\nAnd a final paragraph that rambles on for a while to test how a long note is displayed on the card.",
    tags: ["reading","article","book","work","recipe","travel","reference","video","tutorial","longtag-that-is-quite-wide"],
    readLater: true, archived: false,
  });
  bookmarks = out;
}
if (new URLSearchParams(location.search).get("seed") === "1") {
  seedSampleData();
}

