  if (currentSort === "newest") a.sort((x, y) => y.seq - x.seq);
  else if (currentSort === "oldest") a.sort((x, y) => x.seq - y.seq);
  else if (currentSort === "az") a.sort((x, y) => (x.title || "").localeCompare(y.title || "", undefined, { sensitivity: "base" }));
  else if (currentSort === "za") a.sort((x, y) => (y.title || "").localeCompare(x.title || "", undefined, { sensitivity: "base" }));
  return a;
}

