// --- Sort control (three UI variants to compare via ?sort_ui=) ---
const SORTS = ["newest", "oldest", "az", "za"];
const sortRow = document.getElementById("sortRow");
const sortUi = new URLSearchParams(location.search).get("sort_ui") || "segmented";
function setSort(s) { currentSort = s; renderSortControl(); render(); }
function renderSortControl() {
  if (sortUi === "select") {
    sortRow.innerHTML = `<span class="label">Sort</span>
      <select id="sortSelect">${SORTS.map(s => `<option value="${s}" ${s===currentSort?"selected":""}>${sortLabel(s)}</option>`).join("")}</select>`;
    sortRow.querySelector("#sortSelect").addEventListener("change", (e) => setSort(e.target.value));
  } else if (sortUi === "menu") {
    sortRow.innerHTML = `<span class="label">Sort</span>
      <div class="sortmenu" id="sortMenu">
        <button type="button" id="sortMenuBtn">${sortLabel(currentSort)} ▾</button>
        <div class="menu" id="sortMenuList">
          ${SORTS.map(s => `<button type="button" data-s="${s}" class="${s===currentSort?"active":""}">${sortLabel(s)}</button>`).join("")}
        </div>
      </div>`;
    const btn = sortRow.querySelector("#sortMenuBtn");
    const menu = sortRow.querySelector("#sortMenuList");
    btn.addEventListener("click", (e) => { e.stopPropagation(); menu.classList.toggle("open"); });
    menu.querySelectorAll("button").forEach(b => b.addEventListener("click", () => { menu.classList.remove("open"); setSort(b.dataset.s); }));
    document.addEventListener("click", () => menu.classList.remove("open"), { once: true });
  } else { // segmented (default)
    sortRow.innerHTML = `<span class="label">Sort</span>
      <div class="seg">${SORTS.map(s => `<button type="button" data-s="${s}" class="${s===currentSort?"active":""}">${sortLabel(s)}</button>`).join("")}</div>`;
    sortRow.querySelectorAll(".seg button").forEach(b => b.addEventListener("click", () => setSort(b.dataset.s)));
  }
}

