  if (!looksLikeUrl(url)) {
    showSaveError("That doesn't look like a web address. Try something like example.com or https://example.com.");
    return;
  }
  clearSaveError();
  const key = normalizeUrl(url);
  // Duplicate: don't add a second copy — bring up the one already saved.
  const existing = bookmarks.find(b => b.key === key);
  if (existing) {
