    if (existing.loading) { flashCard(key); return; }
    if (existing.archived) {
      currentView = "archived";
      document.querySelectorAll("#tabs .tab").forEach(t => t.classList.toggle("active", t.dataset.view === "archived"));
      render();
      showToast("This link is archived. Opening it — use Restore to bring it back.");
    } else {
      showToast("You already saved this — opening it so you can update it.");
    }
    openEditor(key);
    return;
