.listtools { display: flex; justify-content: flex-end; margin-top: 12px; }
.select-btn {
  border: 1px solid var(--line); background: #fff; color: var(--ink);
  border-radius: 8px; padding: 7px 14px; font-size: 13px; font-weight: 600; cursor: pointer;
}
.select-btn.active { background: var(--ink); color: #fff; border-color: var(--ink); }
.checkcol { flex: none; display: flex; align-items: center; padding-right: 2px; }
.checkcol input { width: 18px; height: 18px; cursor: pointer; }
.card.selected { outline: 2px solid var(--accent); outline-offset: -1px; }
.bulkbar {
  position: fixed; left: 0; right: 0; bottom: 0; background: var(--ink); color: #fff;
  z-index: 45; box-shadow: 0 -6px 20px rgba(0,0,0,.2);
}
.bulkbar-inner {
  max-width: 760px; margin: 0 auto; padding: 10px 14px; display: flex;
  align-items: center; gap: 8px; flex-wrap: wrap; font-size: 13px;
}
.bulkbar .bulk-link { background: transparent; border: none; color: #9ecbff; cursor: pointer; font-size: 13px; font-weight: 600; }
.bulkbar .bulk-sep { width: 1px; height: 18px; background: rgba(255,255,255,.25); }
.bulkbar .bulk-spacer { flex: 1; }
.bulkbar .bulk-act {
  background: rgba(255,255,255,.12); border: 1px solid rgba(255,255,255,.2); color: #fff;
  border-radius: 8px; padding: 6px 10px; font-size: 13px; font-weight: 600; cursor: pointer;
}
.bulkbar .bulk-act:hover { background: rgba(255,255,255,.22); }
.bulkbar .bulk-act.danger { background: #dc2626; border-color: #dc2626; }
.bulkbar .bulk-done { background: #fff; color: var(--ink); border: none; border-radius: 8px; padding: 6px 14px; font-weight: 700; cursor: pointer; }
.bulk-remove-tag {
  display: inline-flex; align-items: center; gap: 6px; margin: 4px 6px 0 0;
  background: var(--accent-soft); color: var(--accent); border: 1px solid #cdd9ff;
  border-radius: 999px; padding: 4px 12px; font-size: 13px; font-weight: 600; cursor: pointer;
}
.card.clickable { cursor: pointer; transition: box-shadow .15s; }

