// --- Multi-select & bulk actions ---
const selectBtn = document.getElementById("selectBtn");
const bulkbar = document.getElementById("bulkbar");
function toggleSelected(key) {
  if (selected.has(key)) selected.delete(key); else selected.add(key);
  render();
}
function enterSelection() { selectionMode = true; selectBtn.classList.add("active"); selectBtn.textContent = "Cancel select"; render(); }
function exitSelection() { selectionMode = false; selected.clear(); selectBtn.classList.remove("active"); selectBtn.textContent = "Select"; render(); }
selectBtn.addEventListener("click", () => { selectionMode ? exitSelection() : enterSelection(); });

function selectedList() { return bookmarks.filter(b => selected.has(b.key)); }
function updateBulkBar() {
  bulkbar.hidden = !selectionMode;
  if (!selectionMode) { document.body.style.paddingBottom = ""; return; }
  document.body.style.paddingBottom = "72px";
  const n = selected.size;
  document.getElementById("bulkCount").textContent = n + " selected";
  const matching = visibleBookmarks().length;
  document.getElementById("selectAllBtn").textContent = `Select all ${matching} matching`;
  // Archive vs Restore depends on the active view.
  document.getElementById("bulkArchive").hidden = currentView === "archived";
  document.getElementById("bulkRestore").hidden = currentView !== "archived";
}
document.querySelector("#bulkbar .bulkbar-inner").addEventListener("click", (e) => {
  const btn = e.target.closest("button"); if (!btn) return;
  const act = btn.dataset.act;
  if (act === "done") return exitSelection();
  if (act === "clear") { selected.clear(); return render(); }
  if (act === "selectAll") { visibleBookmarks().forEach(b => selected.add(b.key)); return render(); }
  if (selected.size === 0) { showToast("Select some bookmarks first."); return; }
  const items = selectedList();
  if (act === "readlater") { items.forEach(b => b.readLater = true); render(); showToast(`Marked ${items.length} to read later.`); }
  else if (act === "read") { items.forEach(b => b.readLater = false); render(); showToast(`Marked ${items.length} as read.`); }
  else if (act === "archive") { items.forEach(b => b.archived = true); selected.clear(); render(); showToast(`Archived ${items.length}.`); }
  else if (act === "restore") { items.forEach(b => b.archived = false); selected.clear(); render(); showToast(`Restored ${items.length}.`); }
  else if (act === "delete") { askBulkDelete(items.length); }
  else if (act === "addTag") { openBulkTag("add"); }
  else if (act === "removeTag") { openBulkTag("remove"); }
});

// Bulk delete confirmation reuses a dedicated dialog
function askBulkDelete(count) {
  deleteKey = "__bulk__";
  confirmTarget.textContent = count + " selected bookmark" + (count === 1 ? "" : "s");
  confirmBackdrop.querySelector("h2").textContent = "Delete these bookmarks?";
  confirmBackdrop.classList.add("open");
}

// Bulk tag add/remove dialog
const bulkTagBackdrop = document.getElementById("bulkTagBackdrop");
const bulkTagBody = document.getElementById("bulkTagBody");
let bulkTagMode = "add";
function openBulkTag(mode) {
  bulkTagMode = mode;
  const applyBtn = document.getElementById("bulkTagApply");
  document.getElementById("bulkTagSub").textContent = selected.size + " bookmark(s) selected";
  if (mode === "add") {
    document.getElementById("bulkTagTitle").textContent = "Add a tag to selected";
    const known = allKnownTags();
    bulkTagBody.innerHTML = `
      <input type="text" id="bulkTagInput" list="bulkTagList" placeholder="Type a tag" style="width:100%;padding:10px 12px;border:1px solid var(--line);border-radius:8px;font-size:14px;" />
      <datalist id="bulkTagList">${known.map(t => `<option value="${escapeHtml(t)}"></option>`).join("")}</datalist>`;
    applyBtn.hidden = false; applyBtn.textContent = "Add tag";
  } else {
    document.getElementById("bulkTagTitle").textContent = "Remove a tag from selected";
    renderBulkRemoveTags();
    applyBtn.hidden = true;
  }
  bulkTagBackdrop.classList.add("open");
  const inp = document.getElementById("bulkTagInput"); if (inp) inp.focus();
}
function renderBulkRemoveTags() {
  const union = new Map();
  selectedList().forEach(b => (b.tags || []).forEach(t => union.set(t.toLowerCase(), t)));
  const tags = [...union.values()];
  bulkTagBody.innerHTML = tags.length
    ? `<p style="font-size:13px;color:var(--muted);margin:0 0 6px;">Click a tag to remove it from all selected:</p>` +
      tags.map(t => `<button class="bulk-remove-tag" data-t="${escapeHtml(t)}" type="button">${escapeHtml(t)} ✕</button>`).join("")
    : `<p style="font-size:14px;color:var(--muted);">The selected bookmarks have no tags.</p>`;
  bulkTagBody.querySelectorAll(".bulk-remove-tag").forEach(btn => btn.addEventListener("click", () => {
    const t = btn.dataset.t.toLowerCase();
    selectedList().forEach(b => { b.tags = (b.tags || []).filter(x => x.toLowerCase() !== t); });
    renderBulkRemoveTags(); render();
  }));
}
function closeBulkTag() { bulkTagBackdrop.classList.remove("open"); }
document.getElementById("bulkTagCancel").addEventListener("click", closeBulkTag);
bulkTagBackdrop.addEventListener("click", (e) => { if (e.target === bulkTagBackdrop) closeBulkTag(); });
document.getElementById("bulkTagApply").addEventListener("click", () => {
  if (bulkTagMode === "add") {
    const val = (document.getElementById("bulkTagInput").value || "").trim();
    if (!val) { closeBulkTag(); return; }
    let n = 0;
    selectedList().forEach(b => {
      b.tags = b.tags || [];
      if (!b.tags.some(t => t.toLowerCase() === val.toLowerCase())) { b.tags.push(val); n++; }
    });
    closeBulkTag(); render(); showToast(`Added “${val}” to ${n} bookmark(s).`);
  }
});

