// --- Saved searches (collections) ---
let collections = [];   // { id, name, query }
let activeCollection = null;
const collectionsEl = document.getElementById("collections");
const saveSearchBtn = document.getElementById("saveSearchBtn");
const collBackdrop = document.getElementById("collBackdrop");
function renderCollections() {
  collectionsEl.innerHTML = collections.length
    ? collections.map(c =>
        `<span class="coll-chip ${activeCollection===c.id?"active":""}" data-id="${c.id}">
           <button class="open" type="button">${escapeHtml(c.name)}</button>
           <button class="del" type="button" title="Remove collection">×</button>
         </span>`).join("")
    : `<span class="coll-none">none yet — run a search and save it</span>`;
  collectionsEl.querySelectorAll(".coll-chip").forEach(chip => {
    const id = chip.dataset.id;
    chip.querySelector(".open").addEventListener("click", () => openCollection(id));
    chip.querySelector(".del").addEventListener("click", () => {
      collections = collections.filter(c => c.id !== id);
      if (activeCollection === id) activeCollection = null;
      renderCollections();
      showToast("Collection removed.");
    });
  });
}
function openCollection(id) {
  const c = collections.find(x => x.id === id);
  if (!c) return;
  activeCollection = id;
  currentView = "all";
  document.querySelectorAll("#tabs .tab").forEach(t => t.classList.toggle("active", t.dataset.view === "all"));
  const el = document.getElementById("search");
  el.value = c.query;
  setSearchQuery(c.query);
  document.getElementById("searchClear").hidden = !c.query;
  render();
  renderCollections();
  window.scrollTo({ top: 0, behavior: "smooth" });
  showToast(`Showing “${c.name}” — live matches.`);
}
saveSearchBtn.addEventListener("click", () => {
  document.getElementById("collName").value = "";
  document.getElementById("collQuery").value = searchQuery;
  collBackdrop.classList.add("open");
  document.getElementById("collName").focus();
});
document.getElementById("collCancel").addEventListener("click", () => collBackdrop.classList.remove("open"));
collBackdrop.addEventListener("click", (e) => { if (e.target === collBackdrop) collBackdrop.classList.remove("open"); });
document.getElementById("collSave").addEventListener("click", () => {
  const name = document.getElementById("collName").value.trim();
  const query = document.getElementById("collQuery").value.trim();
  if (!name) { showToast("Give the collection a name."); return; }
  if (!query) { showToast("A collection needs a search to run."); return; }
  const id = "c" + Date.now();
  collections.push({ id, name, query });
  collBackdrop.classList.remove("open");
  renderCollections();
  showToast(`Saved collection “${name}”.`);
});
function updateSaveSearchBtn() {
  saveSearchBtn.disabled = !searchQuery;
  // Leaving a collection's exact query means we're no longer "in" it.
  if (activeCollection) {
    const c = collections.find(x => x.id === activeCollection);
    if (!c || c.query !== searchQuery) { activeCollection = null; renderCollections(); }
  }
}

// --- Multi-select & bulk actions ---

