function openHref(url) {
  return /^https?:\/\//i.test(url) ? url : "https://" + url;
}
function isPdfUrl(url) {
  try { return /\.pdf($|[?#])/i.test(new URL(openHref(url)).pathname + (url.split("?")[1] ? "?" + url.split("?")[1] : "")); }
  catch { return /\.pdf($|[?#])/i.test(url); }
}
function fmtDate(ts) {
  try { return new Date(ts).toLocaleString(); } catch { return String(ts); }
}
// Prototype stand-in: open a generated page representing the preserved copy.
function viewSnapshot(b) {
  if (!b.snapshot) return;
  if (b.snapshot.isPdf) {
    const html = `<!doctype html><meta charset="utf-8"><title>Preserved PDF</title>
      <body style="font-family:sans-serif;max-width:640px;margin:40px auto;color:#222;">
      <div style="border:2px solid #c0392b;border-radius:10px;padding:24px;">
      <h2>📄 Preserved PDF (prototype stand-in)</h2>
      <p>In the real app this opens the <b>actual PDF file</b> captured on
      ${fmtDate(b.snapshot.savedAt)} for:</p>
      <p><a href="${escapeHtml(openHref(b.url))}">${escapeHtml(b.title || b.url)}</a></p>
      </div></body>`;
    const u = URL.createObjectURL(new Blob([html], { type: "text/html" }));
    window.open(u, "_blank", "noopener");
    return;
  }
  const html = `<!doctype html><meta charset="utf-8"><title>Preserved copy — ${escapeHtml(b.title || b.url)}</title>
    <body style="font-family:sans-serif;max-width:680px;margin:32px auto;color:#222;line-height:1.5;">
    <div style="background:#eaf7ee;border:1px solid #b6e3c4;border-radius:8px;padding:10px 14px;font-size:13px;color:#1c7a3e;">
      Preserved copy captured on ${fmtDate(b.snapshot.savedAt)} — shown even if the original changes or disappears.
      <span style="color:#666;">(Prototype stand-in for the saved page content.)</span>
    </div>
    <h1>${escapeHtml(b.title || b.url)}</h1>
    <p style="color:#666;">${escapeHtml(openHref(b.url))}</p>
    <p>${escapeHtml(b.desc || "")}</p>
    <hr><p style="color:#888;font-size:13px;">A real capture would store the page's text and images here.</p>
    </body>`;
  const u = URL.createObjectURL(new Blob([html], { type: "text/html" }));
  window.open(u, "_blank", "noopener");
}

