// Automatic preserved-copy capture (simulated). Failures are shown clearly and
// can be retried from Edit. "flaky" hosts fail once then succeed on retry;
// "nosnap"/"unreachable" hosts keep failing to demonstrate a persistent failure.
function captureSnapshot(b) {
  b.snapshotPending = true;
  b.snapshotFailed = false;
  b.snapAttempts = (b.snapAttempts || 0) + 1;
  render();
  if (editingKey === b.key) renderSnapshotArea(b);
  setTimeout(() => {
    b.snapshotPending = false;
    const host = (b.host || "").toLowerCase();
    const persistentFail = /unreachable|nosnap/.test(host);
    const flakyFail = /flaky/.test(host) && b.snapAttempts === 1;
    if (persistentFail || flakyFail) {
      b.snapshotFailed = true;
    } else {
      b.snapshot = { savedAt: Date.now(), isPdf: isPdfUrl(b.url) };
      b.snapshotFailed = false;
    }
    render();
    if (editingKey === b.key) renderSnapshotArea(b);
  }, 700);
}

