// --- Import / Export (standard bookmarks HTML file) ---
function htmlEsc(s) { return (s || "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;"); }
function generateBookmarksHtml() {
  let out = `<!DOCTYPE NETSCAPE-Bookmark-file-1>\n` +
    `<META HTTP-EQUIV="Content-Type" CONTENT="text/html; charset=UTF-8">\n` +
    `<TITLE>Bookmarks</TITLE>\n<H1>Bookmarks</H1>\n<DL><p>\n`;
  for (const b of bookmarks) {
    const add = Math.floor((b.createdAt != null ? b.createdAt : Date.now()) / 1000);
    const tags = (b.tags || []).join(",");
    out += `    <DT><A HREF="${htmlEsc(openHref(b.url))}" ADD_DATE="${add}"` +
      (tags ? ` TAGS="${htmlEsc(tags)}"` : "") + `>${htmlEsc(b.title || b.url)}</A>\n`;
  }
  out += `</DL><p>\n`;
  return out;
}
function exportBookmarks() {
  const blob = new Blob([generateBookmarksHtml()], { type: "text/html" });
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = "bookmarks.html";
  document.body.appendChild(a); a.click(); a.remove();
  showToast(`Exported ${bookmarks.length} bookmark(s) to bookmarks.html.`);
}
const GENERIC_FOLDERS = /^(bookmarks(\s*(bar|menu|toolbar))?|favorites|favourites|other bookmarks|mobile bookmarks|bookmarks toolbar)$/i;
function importBookmarksHtml(text) {
  const doc = new DOMParser().parseFromString(text, "text/html");
  const anchors = [...doc.querySelectorAll("a")];
  let added = 0, skipped = 0;
  for (const a of anchors) {
    const url = a.getAttribute("href");
    if (!url || !/^https?:/i.test(url)) continue;
    const key = normalizeUrl(url);
    if (bookmarks.some(b => b.key === key)) { skipped++; continue; }
    const title = (a.textContent || "").trim() || url;
    const addDate = parseInt(a.getAttribute("add_date") || "", 10);
    const createdAt = addDate ? addDate * 1000 : Date.now();
    let tags = [];
    const tagsAttr = a.getAttribute("tags");
    if (tagsAttr) tags = tagsAttr.split(",").map(s => s.trim()).filter(Boolean);
    // Map the enclosing folder name to a tag (skips generic root folders).
    const dl = a.closest("dl");
    let prev = dl ? dl.previousElementSibling : null;
    let h3 = prev ? (prev.tagName === "H3" ? prev : (prev.querySelector ? prev.querySelector("h3") : null)) : null;
    if (h3) {
      const f = (h3.textContent || "").trim();
      if (f && !GENERIC_FOLDERS.test(f)) tags.push(f);
    }
    tags = [...new Map(tags.map(t => [t.toLowerCase(), t])).values()];
    const meta = metadataFor(url);
    bookmarks.push({
      url, key, loading: false, seq: ++seqCounter, createdAt,
      title, desc: meta.desc, favicon: meta.favicon, preview: null, note: "", tags,
      readLater: false, archived: false, snapshot: null,
    });
    added++;
  }
  render();
  showToast(`Imported ${added} bookmark(s)${skipped ? `, skipped ${skipped} already saved` : ""}.`);
}
document.getElementById("exportBtn").addEventListener("click", exportBookmarks);
const importFile = document.getElementById("importFile");
document.getElementById("importBtn").addEventListener("click", () => importFile.click());
importFile.addEventListener("change", () => {
  const f = importFile.files && importFile.files[0];
  if (!f) return;
  const reader = new FileReader();
  reader.onload = () => { importBookmarksHtml(String(reader.result || "")); importFile.value = ""; };
  reader.readAsText(f);
});

// --- Saved searches (collections) ---

