// --- Personal settings ---
const settings = { defaultSort: "newest", density: "comfortable", fontSize: "medium" };
function applySettings() {
  document.body.classList.remove("density-comfortable", "density-cozy", "density-compact");
  document.body.classList.add("density-" + settings.density);
  document.body.classList.remove("font-small", "font-medium", "font-large");
  document.body.classList.add("font-" + settings.fontSize);
}
function markSeg(container, value) {
  container.querySelectorAll("button").forEach(b => b.classList.toggle("active", b.dataset.v === value));
}
const settingsBackdrop = document.getElementById("settingsBackdrop");
document.getElementById("settingsBtn").addEventListener("click", () => {
  document.getElementById("setSort").value = settings.defaultSort;
  markSeg(document.getElementById("setDensity"), settings.density);
  markSeg(document.getElementById("setFont"), settings.fontSize);
  settingsBackdrop.classList.add("open");
});
document.getElementById("setSort").addEventListener("change", (e) => {
  settings.defaultSort = e.target.value;
  currentSort = settings.defaultSort;   // apply now too
  renderSortControl();
  render();
});
document.getElementById("setDensity").addEventListener("click", (e) => {
  const b = e.target.closest("button"); if (!b) return;
  settings.density = b.dataset.v; markSeg(e.currentTarget, settings.density); applySettings();
});
document.getElementById("setFont").addEventListener("click", (e) => {
  const b = e.target.closest("button"); if (!b) return;
  settings.fontSize = b.dataset.v; markSeg(e.currentTarget, settings.fontSize); applySettings();
});
document.getElementById("settingsClose").addEventListener("click", () => { settingsBackdrop.classList.remove("open"); showToast("Settings saved."); });
settingsBackdrop.addEventListener("click", (e) => { if (e.target === settingsBackdrop) settingsBackdrop.classList.remove("open"); });

