:root {
  --bg: #f5f6f8; --card: #ffffff; --ink: #1f2430; --muted: #6b7280;
  --line: #e5e7eb; --accent: #2563eb; --accent-soft: #eef2ff;
}
* { box-sizing: border-box; }
body { margin: 0; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif; background: var(--bg); color: var(--ink); }

/* login */
.login-body { display: grid; place-items: center; min-height: 100vh; }
.login-card { background: var(--card); border: 1px solid var(--line); border-radius: 14px; padding: 28px; width: 340px; max-width: 92vw; box-shadow: 0 12px 40px rgba(0,0,0,.08); display: flex; flex-direction: column; }
.login-card h1 { margin: 0 0 4px; font-size: 22px; }
.login-sub { margin: 0 0 18px; color: var(--muted); font-size: 14px; }
.login-card label { font-size: 13px; font-weight: 600; margin: 10px 0 5px; }
.login-card input { padding: 11px 12px; border: 1px solid var(--line); border-radius: 8px; font-size: 15px; }
.login-card button { margin-top: 18px; padding: 12px; border: none; border-radius: 8px; background: var(--accent); color: #fff; font-size: 15px; font-weight: 600; cursor: pointer; }
.login-error { color: #c0392b; font-size: 13px; margin-top: 10px; font-weight: 600; }
.login-hint { color: var(--muted); font-size: 12px; margin-top: 14px; text-align: center; }

/* header */
header { background: var(--card); border-bottom: 1px solid var(--line); padding: 16px 20px; }
.header-row { max-width: 820px; margin: 0 auto; display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; }
header h1 { margin: 0; font-size: 20px; }
.tagline { margin: 4px 0 0; color: var(--muted); font-size: 13px; }
.header-actions { display: flex; gap: 8px; flex-wrap: wrap; flex: none; }
.hdr-btn { border: 1px solid var(--line); background: #fff; color: var(--ink); border-radius: 8px; padding: 8px 12px; font-size: 13px; font-weight: 600; cursor: pointer; }
.hdr-btn:hover { background: var(--bg); }

main { max-width: 820px; margin: 0 auto; padding: 20px 16px 90px; }

.saver { background: var(--card); border: 1px solid var(--line); border-radius: 12px; padding: 16px; display: flex; gap: 10px; flex-wrap: wrap; }
.saver input[type=text] { flex: 1 1 320px; min-width: 0; padding: 12px 14px; border: 1px solid var(--line); border-radius: 8px; font-size: 15px; }
.saver button { padding: 12px 20px; border: none; border-radius: 8px; background: var(--accent); color: #fff; font-size: 15px; font-weight: 600; cursor: pointer; }
.saver button:disabled { opacity: .55; cursor: default; }
.hint { color: var(--muted); font-size: 13px; margin: 8px 2px 0; }
.save-error { color: #c0392b; font-size: 13px; margin: 8px 2px 0; font-weight: 600; }

.tabs { display: flex; gap: 8px; margin-top: 22px; flex-wrap: wrap; }
.tab { border: 1px solid var(--line); background: #fff; color: var(--muted); border-radius: 999px; padding: 8px 16px; font-size: 14px; font-weight: 600; cursor: pointer; }
.tab.active { background: var(--ink); color: #fff; border-color: var(--ink); }
.tab .count { display: inline-block; min-width: 18px; text-align: center; font-size: 12px; background: var(--accent); color: #fff; border-radius: 999px; padding: 0 6px; margin-left: 4px; }
.tab.active .count { background: rgba(255,255,255,.25); }

.searchbar { margin-top: 14px; display: flex; align-items: center; gap: 8px; background: #fff; border: 1px solid var(--line); border-radius: 10px; padding: 4px 10px; }
.searchbar .search-icon { font-size: 14px; opacity: .6; }
.searchbar input { border: none; outline: none; flex: 1; font-size: 15px; padding: 9px 4px; background: transparent; }
.search-clear { border: none; background: transparent; font-size: 20px; line-height: 1; color: var(--muted); cursor: pointer; padding: 0 6px; }

.collections-row { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; margin-top: 12px; }
.coll-label { font-size: 13px; color: var(--muted); font-weight: 600; }
.collections { display: flex; gap: 6px; flex-wrap: wrap; flex: 1; }
.coll-chip { display: inline-flex; align-items: center; gap: 6px; background: #eef4ff; color: #1e40af; border: 1px solid #cdd9ff; border-radius: 999px; padding: 4px 6px 4px 12px; font-size: 13px; font-weight: 600; }
.coll-chip.active { background: #1e40af; color: #fff; border-color: #1e40af; }
.coll-chip .open { background: transparent; border: none; color: inherit; cursor: pointer; font: inherit; padding: 0; }
.coll-chip .del { background: transparent; border: none; color: inherit; cursor: pointer; font-size: 14px; line-height: 1; opacity: .7; padding: 0 3px; }
.coll-none { font-size: 13px; color: var(--muted); font-style: italic; }
.save-search { border: 1px solid var(--line); background: #fff; color: var(--ink); border-radius: 8px; padding: 6px 12px; font-size: 13px; font-weight: 600; cursor: pointer; white-space: nowrap; }
.save-search:disabled { opacity: .5; cursor: default; }

.sortrow { display: flex; align-items: center; gap: 8px; margin-top: 14px; flex-wrap: wrap; }
.sortrow .label { font-size: 13px; color: var(--muted); font-weight: 600; }
.sortrow select { padding: 7px 10px; border: 1px solid var(--line); border-radius: 8px; font-size: 14px; font-family: inherit; }
.sortrow .spacer { flex: 1; }
.select-btn { border: 1px solid var(--line); background: #fff; color: var(--ink); border-radius: 8px; padding: 7px 14px; font-size: 13px; font-weight: 600; cursor: pointer; }
.select-btn.active { background: var(--ink); color: #fff; border-color: var(--ink); }

.list { margin-top: 16px; display: flex; flex-direction: column; gap: 12px; }
.card { background: var(--card); border: 1px solid var(--line); border-radius: 12px; padding: 14px 16px; display: flex; gap: 12px; align-items: flex-start; }
.card.clickable { cursor: pointer; transition: box-shadow .15s; }
.card.clickable:hover { box-shadow: 0 3px 12px rgba(0,0,0,.07); }
.card.selected { outline: 2px solid var(--accent); outline-offset: -1px; }
.card.flash { animation: flash 1.4s ease; }
@keyframes flash { 0% { box-shadow: 0 0 0 0 rgba(37,99,235,0);} 25% { box-shadow: 0 0 0 4px rgba(37,99,235,.18);} 100% { box-shadow: 0 0 0 0 rgba(37,99,235,0);} }
.checkcol { flex: none; display: flex; align-items: center; }
.checkcol input { width: 18px; height: 18px; cursor: pointer; }
.favicon { width: 34px; height: 34px; border-radius: 8px; background: var(--accent-soft); display: grid; place-items: center; font-weight: 700; color: var(--accent); flex: none; font-size: 15px; overflow: hidden; }
.favicon img { width: 22px; height: 22px; display: block; }
.card .body { flex: 1; min-width: 0; }
.card .preview { width: 100%; height: 132px; object-fit: cover; border-radius: 8px; margin-bottom: 8px; display: block; border: 1px solid var(--line); }
.card .title { font-weight: 600; font-size: 15px; margin: 0 0 3px; }
.card .title a { color: var(--ink); text-decoration: none; }
.card .title a:hover { text-decoration: underline; }
.card .desc { color: var(--muted); font-size: 13px; margin: 0 0 6px; line-height: 1.4; display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }
.card .site { color: var(--accent); font-size: 12px; word-break: break-all; }
.toread-flag { display: inline-block; font-size: 11px; font-weight: 700; color: #b7791f; background: #fff7e6; border: 1px solid #f0c469; border-radius: 999px; padding: 1px 8px; margin-bottom: 4px; }
.fetch-warn { color: #b7791f; font-size: 12.5px; margin: 2px 0 6px; }
.note { margin: 6px 0 0; font-size: 13px; color: var(--ink); background: #fffbea; border: 1px solid #f4e6a8; border-radius: 8px; padding: 8px 10px; white-space: pre-wrap; }
.note a { color: var(--accent); } .note ul { margin: 4px 0; padding-left: 20px; } .note code { background: #f3eecb; padding: 1px 4px; border-radius: 4px; font-size: 12px; } .note p { margin: 4px 0; } .note p:first-child { margin-top: 0; } .note p:last-child { margin-bottom: 0; }
.tags { margin-top: 8px; display: flex; flex-wrap: wrap; gap: 6px; }
.tag { font-size: 12px; background: var(--accent-soft); color: var(--accent); padding: 3px 9px; border-radius: 999px; font-weight: 600; border: none; cursor: pointer; font-family: inherit; }
.tag:hover { background: #dfe6ff; text-decoration: underline; }
.snap-badge { display: inline-flex; align-items: center; gap: 4px; margin-top: 6px; background: #eaf7ee; border: 1px solid #b6e3c4; color: #1c7a3e; border-radius: 999px; padding: 2px 10px; font-size: 12px; font-weight: 600; cursor: pointer; }
.snap-badge.pending { background: #eef2ff; border-color: #cdd9ff; color: #3a5bd0; cursor: default; }
.snap-badge.failed { background: #fdeaea; border-color: #f0c4c4; color: #c0392b; }
.col-actions { display: flex; flex-direction: column; gap: 6px; align-items: stretch; flex: none; }
.col-actions button { border: 1px solid var(--line); background: #fff; color: var(--ink); border-radius: 8px; padding: 6px 12px; font-size: 13px; font-weight: 600; cursor: pointer; white-space: nowrap; }
.readlater-btn.on { background: #fff7e6; border-color: #f0c469; color: #b7791f; }
.restore-btn { color: var(--accent); border-color: #bcd0ff !important; }
.delete-btn { color: #c0392b; border-color: #f0c4c4 !important; }
.archiveorg-badge { color: var(--muted); font-size: 11px; }

.empty { text-align: center; color: var(--muted); padding: 48px 20px; border: 1px dashed var(--line); border-radius: 12px; margin-top: 16px; }

/* density */
.density-cozy .card .preview { height: 88px; }
.density-cozy .card .desc { -webkit-line-clamp: 2; }
.density-compact .card { padding: 9px 12px; }
.density-compact .card .preview, .density-compact .card .desc, .density-compact .card .note { display: none; }
/* text size */
.font-small .card .title { font-size: 13px; } .font-small .card .desc, .font-small .card .note { font-size: 12px; }
.font-large .card .title { font-size: 17px; } .font-large .card .desc, .font-large .card .note { font-size: 15px; } .font-large .card .site { font-size: 13px; }

/* modal */
.backdrop { position: fixed; inset: 0; background: rgba(15,20,30,.45); display: none; align-items: flex-start; justify-content: center; padding: 40px 16px; overflow-y: auto; z-index: 50; }
.backdrop.open { display: flex; }
.modal { background: var(--card); border-radius: 14px; width: 100%; max-width: 520px; padding: 22px; box-shadow: 0 20px 60px rgba(0,0,0,.25); }
.modal h2 { margin: 0 0 4px; font-size: 18px; }
.modal .sub { margin: 0 0 16px; color: var(--muted); font-size: 13px; word-break: break-all; }
.field { margin-bottom: 14px; }
.field label { display: block; font-size: 13px; font-weight: 600; margin-bottom: 5px; }
.field input[type=text], .field textarea, .field select { width: 100%; padding: 10px 12px; border: 1px solid var(--line); border-radius: 8px; font-size: 14px; font-family: inherit; }
.field textarea { resize: vertical; min-height: 60px; }
.fieldhint { font-size: 12px; color: var(--muted); margin: 6px 0 0; }
.inline-check { font-weight: 400 !important; margin-top: 10px; display: flex; gap: 8px; align-items: center; font-size: 13px; cursor: pointer; }
.archiveorg-area { font-size: 13px; margin-top: 6px; }
.chipbox { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; border: 1px solid var(--line); border-radius: 8px; padding: 7px 8px; }
.chipbox .chip { display: inline-flex; align-items: center; gap: 6px; background: var(--accent-soft); color: var(--accent); font-weight: 600; font-size: 12px; padding: 3px 4px 3px 9px; border-radius: 999px; }
.chipbox .chip button { border: none; background: transparent; color: var(--accent); cursor: pointer; font-size: 14px; line-height: 1; padding: 0 3px; }
.chipbox input { border: none; outline: none; flex: 1; min-width: 120px; font-size: 14px; padding: 4px; }
.suggestions { position: absolute; left: 0; right: 0; top: 100%; margin-top: 4px; background: #fff; border: 1px solid var(--line); border-radius: 8px; box-shadow: 0 8px 24px rgba(0,0,0,.12); z-index: 60; overflow: hidden; display: none; }
.suggestions.open { display: block; }
.suggestions .opt { padding: 9px 12px; font-size: 14px; cursor: pointer; }
.suggestions .opt:hover, .suggestions .opt.active { background: var(--accent-soft); color: var(--accent); }
.modal .actions { display: flex; justify-content: flex-end; gap: 10px; margin-top: 18px; }
.btn { padding: 10px 18px; border-radius: 8px; font-size: 14px; font-weight: 600; cursor: pointer; border: 1px solid var(--line); background: #fff; color: var(--ink); }
.btn.primary { background: var(--accent); color: #fff; border-color: var(--accent); }
.btn.danger { background: #dc2626; color: #fff; border-color: #dc2626; }
.danger-note { font-size: 14px; color: var(--muted); margin: 0 0 4px; }
.seg { display: inline-flex; border: 1px solid var(--line); border-radius: 8px; overflow: hidden; }
.seg button { border: none; background: #fff; color: var(--muted); font-size: 13px; font-weight: 600; padding: 8px 14px; cursor: pointer; border-left: 1px solid var(--line); }
.seg button:first-child { border-left: none; }
.seg button.active { background: var(--ink); color: #fff; }
.bulk-remove-tag { display: inline-flex; align-items: center; gap: 6px; margin: 4px 6px 0 0; background: var(--accent-soft); color: var(--accent); border: 1px solid #cdd9ff; border-radius: 999px; padding: 4px 12px; font-size: 13px; font-weight: 600; cursor: pointer; }

/* bulk bar */
